"""Auth views (generated by Shikshya, P1b.6 R2). Sign-in tokens come from django-rest-knox: one per device, stored
hashed, expiring after 12 idle hours and 30 days at most. Sign-in and sign-up are limited to 10 a minute."""
from django.contrib.auth import get_user_model
from django.utils import timezone
from knox.models import AuthToken
from rest_framework import status
from rest_framework.authtoken.views import ObtainAuthToken
from rest_framework.permissions import AllowAny, IsAuthenticated
from rest_framework.response import Response
from rest_framework.throttling import ScopedRateThrottle
from rest_framework.views import APIView

from api.serializers_auth import RegisterSerializer, UserSerializer


def _issue(user):
    """A new token for this device; the user's expired tokens are removed first."""
    AuthToken.objects.filter(user=user, expiry__lt=timezone.now()).delete()
    _, token = AuthToken.objects.create(user)
    return token


class CustomAuthToken(ObtainAuthToken):
    """Sign in with a username or an email and a password."""
    # ObtainAuthToken turns every throttle off; sign-in gets the auth scope back.
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def post(self, request, *args, **kwargs):
        data = request.data.copy()
        username = data.get("username", "")
        if "@" in username:
            match = get_user_model().objects.filter(email__iexact=username).first()
            if match is not None:
                data["username"] = match.get_username()
        serializer = self.serializer_class(data=data, context={"request": request})
        serializer.is_valid(raise_exception=True)
        user = serializer.validated_data["user"]
        return Response({"token": _issue(user), "user": UserSerializer(user).data})


class RegisterView(APIView):
    permission_classes = [AllowAny]
    throttle_scope = "auth"

    def post(self, request):
        serializer = RegisterSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        user = serializer.save()
        return Response({"token": _issue(user), "user": UserSerializer(user).data}, status=status.HTTP_201_CREATED)


class LogoutView(APIView):
    """Sign out on this device: its token stops working at once."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        if isinstance(request.auth, AuthToken):
            request.auth.delete()
        return Response({"detail": "Logged out."}, status=status.HTTP_200_OK)


class LogoutAllView(APIView):
    """Sign out on every device (a lost phone, a changed password)."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        AuthToken.objects.filter(user=request.user).delete()
        return Response({"detail": "Logged out on every device."}, status=status.HTTP_200_OK)


class ProfileView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        return Response(UserSerializer(request.user).data)

    def patch(self, request):
        serializer = UserSerializer(request.user, data=request.data, partial=True)
        serializer.is_valid(raise_exception=True)
        serializer.save()
        return Response(serializer.data)
